/**
 * Cross-language golden contract tests (vitest).
 *
 * Consumes tests/contract/golden/*.json (generated by scripts/generate-golden.py)
 * and validates each fixture against the corresponding zod schema.
 *
 * Strict field-set check: after parsing, we compare the top-level keys of the
 * raw JSON against the keys produced by zod. Because zod strips unknown fields
 * by default, any Python-side key that is not declared in schema.ts will be
 * silently dropped — and this test catches that.
 *
 * Legacy variant: run-legacy-v01x.json uses old aggregation format; it is
 * tested via RunSchema (which has migration preprocessing) and we only assert
 * that parsing succeeds and the migrated decision is correct.
 */

import { describe, it, expect } from "vitest";
import fs from "node:fs";
import path from "node:path";
import {
  RunSchema,
  DecisionReportSchema,
  TraceRefSchema,
  EvaluationResultSchema,
} from "../schema";

// Golden directory relative to this test file:
// ui/src/lib/__tests__/ -> ../../../../tests/contract/golden/
const GOLDEN_DIR = path.resolve(__dirname, "../../../../tests/contract/golden");

function loadGolden(name: string): unknown {
  const filePath = path.join(GOLDEN_DIR, name);
  return JSON.parse(fs.readFileSync(filePath, "utf-8"));
}

// ---------------------------------------------------------------------------
// Strict field-set comparison helper
// ---------------------------------------------------------------------------

/**
 * Assert that no top-level keys present in the raw JSON are silently dropped
 * by the zod schema. Zod strips unknown fields without error by default, so
 * a key mismatch would pass a plain .parse() call.
 *
 * Note: keys that are in the raw object but absent from parsed output indicate
 * that schema.ts is missing a field declaration — a contract drift.
 */
function assertNoStrippedKeys(rawObj: unknown, parsedObj: unknown): void {
  if (typeof rawObj !== "object" || rawObj === null) return;
  if (typeof parsedObj !== "object" || parsedObj === null) return;

  const rawKeys = new Set(Object.keys(rawObj as Record<string, unknown>));
  const parsedKeys = new Set(Object.keys(parsedObj as Record<string, unknown>));

  const stripped = [...rawKeys].filter((k) => !parsedKeys.has(k));
  expect(stripped, `zod silently stripped these fields: ${JSON.stringify(stripped)}`).toEqual([]);
}

// ---------------------------------------------------------------------------
// RunRecord: Phase 2 full variant
// ---------------------------------------------------------------------------

describe("golden: run-phase2-full.json", () => {
  const raw = loadGolden("run-phase2-full.json");

  it("parses without error", () => {
    expect(() => RunSchema.parse(raw)).not.toThrow();
  });

  it("strict: no top-level fields stripped by zod", () => {
    const parsed = RunSchema.parse(raw);
    assertNoStrippedKeys(raw, parsed);
  });

  it("has decision with decision_report_id", () => {
    const run = RunSchema.parse(raw);
    expect(run.decision?.decision_report_id).toBeTruthy();
  });

  it("preserves typed Team Server provenance", () => {
    const run = RunSchema.parse(raw);
    expect(run.owner).toBe("fixture-owner");
    expect(run.server_context).toEqual({
      schema_version: "1.0",
      workspace_id: "ws-20260612T000000Z-12345678",
      owner: "fixture-owner",
      template_id: "phase2-template",
      template_version: "1.0.0",
      job_id: "job-20260612T000000Z-12345678",
      server_name: "fixture-server",
    });
  });

  it("has llm_judge evaluations with rubric_hash", () => {
    const run = RunSchema.parse(raw);
    const judgeEvals = run.evaluations.filter((e) => e.evaluator_type === "llm_judge");
    expect(judgeEvals.length).toBeGreaterThan(0);
    expect(judgeEvals[0].rubric_hash).toBeTruthy();
  });

  it("decision per_configuration has denominator_policy=exclude_failed", () => {
    const run = RunSchema.parse(raw);
    const baseline = run.decision?.aggregation.per_configuration["baseline"];
    expect(baseline?.denominator_policy).toBe("exclude_failed");
  });
});

// ---------------------------------------------------------------------------
// RunRecord: minimal variant
// ---------------------------------------------------------------------------

describe("golden: run-minimal.json", () => {
  const raw = loadGolden("run-minimal.json");

  it("parses without error", () => {
    expect(() => RunSchema.parse(raw)).not.toThrow();
  });

  it("strict: no top-level fields stripped by zod", () => {
    const parsed = RunSchema.parse(raw);
    assertNoStrippedKeys(raw, parsed);
  });

  it("optional fields are null/empty", () => {
    const run = RunSchema.parse(raw);
    expect(run.decision).toBeNull();
    expect(run.same_start_snapshot).toBeNull();
    expect(run.traces).toEqual([]);
  });
});

