// ---------------------------------------------------------------------------
// RunRecord: legacy v0.1.x variant (migration path)
// ---------------------------------------------------------------------------

describe("golden: run-legacy-v01x.json (legacy compat)", () => {
  const raw = loadGolden("run-legacy-v01x.json");

  it("parses without throwing (legacy aggregation migration)", () => {
    expect(() => RunSchema.parse(raw)).not.toThrow();
  });

  it("decision verdict is regressed after migration", () => {
    const run = RunSchema.parse(raw);
    expect(run.decision?.verdict).toBe("regressed");
  });

  it("legacy baseline stats migrated to ConfigurationStats", () => {
    const run = RunSchema.parse(raw);
    const baseline = run.decision?.aggregation.per_configuration["baseline"];
    expect(baseline).toBeDefined();
    expect(baseline?.pass_rate).toBe(1.0);
  });
});
